        sWorld->ShutdownServ(time, SHUTDOWN_MASK_IDLE, exitCode);
    }
    else
        sWorld->ShutdownServ(time, SHUTDOWN_MASK_IDLE, SHUTDOWN_EXIT_CODE);
        return true;
}

